import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"Life — Biology & Meaning","description":"","frontmatter":{},"headers":[],"relativePath":"docs/science/life.md","filePath":"docs/science/life.md"}`),a={name:`docs/science/life.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="life-—-biology-meaning" tabindex="-1">Life — Biology &amp; Meaning <a class="header-anchor" href="#life-—-biology-meaning" aria-label="Permalink to “Life — Biology &amp; Meaning”">​</a></h1><h2 id="the-sealed-truth" tabindex="-1">The Sealed Truth <a class="header-anchor" href="#the-sealed-truth" aria-label="Permalink to “The Sealed Truth”">​</a></h2><p><strong>Theorems:</strong> <code>BioPhysics.lean</code> (16), <code>Neuro.lean</code> (8), <code>Molecular.lean</code> (7)</p><p>DNA bases pair by complement (A↔T, G↔C, the reflection 3−c, self-inverse). Chargaff&#39;s counts balance. Neurons fire all-or-none (threshold, supra-threshold spike, sub-threshold silence). Spatial summation: two sub-threshold inputs sum to fire. Hebbian learning: Δw = pre·post. Octet rule (4+4=8). Bond order gives N₂ triple, O₂ double.</p><p><strong>Why sealed:</strong> These are pure algebra. Base-pairing is a fixed-key XOR (one-time-pad step). Firing is a threshold function. Bonding is electron counting. No philosophy needed — the mechanism as decidable facts.</p><hr><h2 id="the-honest-boundary" tabindex="-1">The Honest Boundary <a class="header-anchor" href="#the-honest-boundary" aria-label="Permalink to “The Honest Boundary”">​</a></h2><p><strong>What biology CANNOT prove:</strong></p><ul><li>Whether life is &quot;special&quot; (vs chemistry that happens to self-replicate)</li><li>Whether consciousness emerges from neurons (correlation ≠ causation)</li><li>Whether the universe is &quot;designed for&quot; life (anthropic principle — that&#39;s cosmology)</li><li>What &quot;meaning&quot; is or whether life has it (pure philosophy)</li></ul><p><strong>Honest scope:</strong> Biology seals the MECHANISM of life (DNA, neurons, bonding). It does not settle whether life is meaningful, special, or the ultimate point of the universe.</p><hr><h2 id="the-metaphysical-pair" tabindex="-1">The Metaphysical Pair <a class="header-anchor" href="#the-metaphysical-pair" aria-label="Permalink to “The Metaphysical Pair”">​</a></h2><p><strong>The Question:</strong> <em>Does understanding life&#39;s mechanism reduce it to &quot;mere chemistry,&quot; or does mechanism and meaning coexist?</em></p><p><strong>The Trinity:</strong></p><table tabindex="0"><thead><tr><th>Perspective</th><th>What It Proves</th><th>What It Cannot</th></tr></thead><tbody><tr><td><strong>Decidable (Sealed)</strong></td><td>DNA replicates because base-pairing is self-inverse (XOR with itself is identity). Neurons fire because voltage exceeds threshold. Molecules bond because electrons redistribute. Every step is mechanical, deterministic, decidable.</td><td>Whether this mechanism is &quot;all there is&quot; to life; whether mechanism and meaning are opposed; whether you are &quot;nothing but&quot; atoms following physical law</td></tr><tr><td><strong>Honest Boundary</strong></td><td>Understanding the mechanism does NOT negate the phenomenon. A song is &quot;nothing but&quot; sound waves (decidable physics) AND a poem (meaningfulness, decided by you). Both are true.</td><td>Whether reducing to mechanism makes something &quot;less real&quot; or &quot;less meaningful&quot;; whether your experiences are diminished by knowing their neural basis</td></tr><tr><td><strong>Metaphysical</strong></td><td>Can life be <em>completely</em> mechanical AND completely meaningful? Does physics + randomness + history = your consciousness, or does something transcend mechanism?</td><td>Whether the universe cares about life; whether your existence is accident or purpose; whether meaning requires being non-mechanical</td></tr></tbody></table><p><strong>The court decides:</strong> Biology seals the mechanism. Philosophy settles whether mechanism precludes meaning. They do not compete — one is how, the other is why.</p><hr><h2 id="read-the-sealed-proofs" tabindex="-1">Read the Sealed Proofs <a class="header-anchor" href="#read-the-sealed-proofs" aria-label="Permalink to “Read the Sealed Proofs”">​</a></h2><p><a href="./../../lean/BioPhysics.lean">BioPhysics.lean</a> — blood, DNA, sound, chemistry, music, acid-base, heredity, colour</p><p><a href="./../../lean/Neuro.lean">Neuro.lean</a> — threshold firing, summation, Hebbian learning, action potential, refractory</p><p><a href="./../../lean/Molecular.lean">Molecular.lean</a> — octet rule, bond order, Lewis structures, valence, electronegativity</p><p>Each proven <code>by decide</code>.</p><hr><h2 id="the-research-question" tabindex="-1">The Research Question <a class="header-anchor" href="#the-research-question" aria-label="Permalink to “The Research Question”">​</a></h2><p>If life is fully mechanical (DNA→protein→neurons→thought) and no step violates physics, then:</p><ol><li>At what point does mechanism become consciousness?</li><li>Is there a &quot;hard problem&quot; of consciousness or just a gap in explanation we&#39;ll eventually fill?</li><li>Can you love, create, find beauty in something you completely understand?</li></ol><p><strong>These are open.</strong> Biology cannot answer them. Only you can.</p>`,27)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};